class Solution:
    def partition(self, s: str) -> list[list[str]]:
        result = []
        path = []
        n = len(s)

        def is_palindrome(sub):
            return sub == sub[::-1]

        def backtrack(start):
            if start == n:
                result.append(path[:])
                return
            for end in range(start, n):
                substr = s[start:end + 1]
                if is_palindrome(substr):
                    path.append(substr)
                    backtrack(end + 1)
                    path.pop()

        backtrack(0)
        return result
